import{_ as t,o as a,c as i,a0 as r}from"./chunks/framework.BxrwG5q5.js";const u=JSON.parse('{"title":"Team Collaboration","description":"","frontmatter":{},"headers":[],"relativePath":"features/team.md","filePath":"features/team.md"}'),o={name:"features/team.md"};function n(l,e,s,d,h,m){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="team-collaboration" tabindex="-1">Team Collaboration <a class="header-anchor" href="#team-collaboration" aria-label="Permalink to &quot;Team Collaboration&quot;">​</a></h1><p>@jewel998/config supports multi-user access with role-based access control (RBAC). Invite team members, assign roles, and ensure no one has more access than they need.</p><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><p>Each project member has one of three roles:</p><table tabindex="0"><thead><tr><th>Role</th><th>Configs</th><th>Segments</th><th>API Keys</th><th>Settings</th><th>Team</th></tr></thead><tbody><tr><td><strong>Viewer</strong></td><td>Read</td><td>Read</td><td>Read</td><td>Read</td><td>Read</td></tr><tr><td><strong>Editor</strong></td><td>Read/Write</td><td>Read/Write</td><td>Read</td><td>Read</td><td>Read</td></tr><tr><td><strong>Admin</strong></td><td>Full</td><td>Full</td><td>Full</td><td>Full</td><td>Full</td></tr></tbody></table><h3 id="viewer" tabindex="-1">Viewer <a class="header-anchor" href="#viewer" aria-label="Permalink to &quot;Viewer&quot;">​</a></h3><ul><li>Can see all configs, segments, and audit logs</li><li>Cannot create, modify, or delete anything</li><li>Useful for: stakeholders, PMs, support teams</li></ul><h3 id="editor" tabindex="-1">Editor <a class="header-anchor" href="#editor" aria-label="Permalink to &quot;Editor&quot;">​</a></h3><ul><li>Can create and modify configs, segments, and targeting rules</li><li>Cannot manage API keys, project settings, or team members</li><li>Useful for: developers, QA engineers</li></ul><h3 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h3><ul><li>Full access to everything including API keys and team management</li><li>Can invite/remove members and change roles</li><li>The project owner is always an admin</li></ul><h2 id="inviting-members" tabindex="-1">Inviting Members <a class="header-anchor" href="#inviting-members" aria-label="Permalink to &quot;Inviting Members&quot;">​</a></h2><ol><li>Go to <strong>Team</strong> in the portal navigation</li><li>Click <strong>Add Member</strong></li><li>Enter their email address</li><li>Select a role (Viewer, Editor, Admin)</li><li>They&#39;ll be added to the project immediately</li></ol><h2 id="removing-members" tabindex="-1">Removing Members <a class="header-anchor" href="#removing-members" aria-label="Permalink to &quot;Removing Members&quot;">​</a></h2><ol><li>Go to <strong>Team</strong> in the portal navigation</li><li>Find the member in the list</li><li>Click the overflow menu (⋮) next to their name</li><li>Select <strong>Remove</strong> — they&#39;ll lose access immediately</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Removing a member is immediate and permanent. They can be re-invited, but will start with no role until assigned one.</p></div><h2 id="changing-roles" tabindex="-1">Changing Roles <a class="header-anchor" href="#changing-roles" aria-label="Permalink to &quot;Changing Roles&quot;">​</a></h2><p>Only Admins can change another member&#39;s role. Go to <strong>Team</strong>, click the role badge next to a member, and select a new role from the dropdown.</p><h2 id="ownership-transfer" tabindex="-1">Ownership Transfer <a class="header-anchor" href="#ownership-transfer" aria-label="Permalink to &quot;Ownership Transfer&quot;">​</a></h2><p>The project owner (first admin) cannot be removed. To transfer ownership:</p><ol><li>Add the new owner as an Admin</li><li>Contact support or modify the Firestore <code>projects/{id}</code> document&#39;s <code>ownerId</code> field directly</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If the sole admin leaves the project, remaining members retain their roles but cannot manage team membership or API keys. Ownership must be reassigned at the Firestore level.</p></div><h2 id="audit-trail" tabindex="-1">Audit Trail <a class="header-anchor" href="#audit-trail" aria-label="Permalink to &quot;Audit Trail&quot;">​</a></h2><p>Every action by every team member is recorded in the audit log:</p><ul><li>Who made the change (actor)</li><li>What was changed (resource path)</li><li>When it happened (timestamp)</li><li>What the old and new values were (diff)</li></ul><p>This gives full accountability and makes it easy to trace back any issue to the specific change and person.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Principle of least privilege</strong> — Start with Viewer, upgrade to Editor when needed</li><li><strong>Production changes</strong> — Only Admins should manage production API keys</li><li><strong>Audit regularly</strong> — Review the audit log for unexpected changes</li><li><strong>Use labels</strong> — Label your API keys by purpose (&quot;Frontend Prod&quot;, &quot;CI/CD&quot;, &quot;Backend Worker&quot;)</li><li><strong>Multiple admins</strong> — Always have at least 2 admins to avoid single-point-of-failure for access management</li></ul>',28)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
